import { IUser } from 'src/services/users.service';

import { IBaseHiking } from '@apps/Hiking/@types/hikingList.types';

export interface IInterview {
  id: number;
  name: string;
  description: string;

  date_start: Date;
  date_finish: Date;

  hello_text: string;
  by_text: string;

  members_limit: number;

  isMain: boolean;

  hiking: null | IBaseHiking;
  author: IUser;
}

export enum IQuestionType {
  Input = 1,
  Select = 2,
  Dir = 3,
}

export interface IQuestionTypeObject {
  id: number;
  name: string;
  canMulti: boolean;
  hint: string;
}

export interface IQuestionBase {
  id: number;
  name: string;
  text: string;
  type: IQuestionType;
  typeObject: IQuestionTypeObject;

  isCustom: boolean;
  isRequire: boolean;
  isMulti: boolean;
  isPrivate: boolean;

  order_index: number;
}

export interface IQuestionInputParams {
  id: number;
  type: string;
  pattern: string;
  placeholder: string;
  min: string;
  max: string;
  step: string;
}

export interface IQuestionSelectParams {
  id: number;
  value: string;
  order_index: number;
}
export interface IQuestionDirParams {
  id: number;
  id_dir: number;
  name: string;
  desc: string;
  table: string;
  field: string;
  value: string;
  isEqual: boolean;
}

export interface IQuestionInput extends IQuestionBase {
  type: IQuestionType.Input;
  params: IQuestionInputParams;
}
export interface IQuestionSelect extends IQuestionBase {
  type: IQuestionType.Select;
  options: IQuestionSelectParams[];
}
export interface IQuestionDir extends IQuestionBase {
  type: IQuestionType.Dir;
  dir: IQuestionDirParams;
}

export type IQuestion = IQuestionInput | IQuestionSelect | IQuestionDir;

export interface IQuestionInputWithAnswer extends IQuestionInput {
  value: string;
  answer_date: Date;
  user: IUser;
}
export interface IQuestionSelectWithAnswer extends IQuestionSelect {
  selectedIds: number[];
  customValue: string | null;
  answer_date: Date;
  user: IUser;
}
export interface IQuestionDirWithAnswer extends IQuestionDir {
  selectedIds: number[];
  customValue: string | null;
  answer_date: Date;
  user: IUser;
}

export type IQuestionWithAnswer =
  | IQuestionInputWithAnswer
  | IQuestionSelectWithAnswer
  | IQuestionDirWithAnswer;
