import { IUser } from 'src/services/users.service';

import { getSQLDate } from '@helpers/dateHelper';

import {
  IInterview,
  IQuestion,
  IQuestionBase,
  IQuestionDir,
  IQuestionInput,
  IQuestionInputParams,
  IQuestionInputWithAnswer,
  IQuestionSelect,
  IQuestionType,
  IQuestionTypeObject,
  IQuestionWithAnswer,
} from '../@types/interview.types';
import {
  IInterviewDTO,
  IInterviewUpdateDTO,
  IIQuestionTypeDTO,
  IQuestionBaseUpdateOrAddDTO,
  IQuestionDTO,
  IQuestionInputParamsUpdateOrAddDTO,
  IQuestionWithMyAnswerDTO,
} from '../@types/interview.types.dto';
import { IQuestionDirParams } from './../@types/interview.types';

export const mapInterviewToFront = (backData: IInterviewDTO): IInterview => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.desc,

    date_start: new Date(backData.date_start),
    date_finish: new Date(backData.date_finish),

    hello_text: backData.hello_text,
    by_text: backData.by_text,

    members_limit: +backData.members_limit,

    isMain: backData.main === '1',

    hiking: !backData.id_hiking
      ? null
      : {
          id: +backData.hiking_id,
          name: backData.hiking_name,
          ava: backData.hiking_ava,
          start: new Date(backData.hiking_start),
          finish: new Date(backData.hiking_finish),
        },
    author: {
      id: +backData.id_author,
      name: backData.user_name,
      surname: backData.user_name,
      photo: backData.user_photo,
    },
  };
};

export const mapInterviewToBack = (frontData: IInterview): IInterviewUpdateDTO => {
  return {
    id: frontData.id,
    name: frontData.name,
    desc: frontData.description,
    hello_text: frontData.hello_text,
    by_text: frontData.by_text,
    member_limit: frontData.members_limit,
    d1: getSQLDate(frontData.date_start),
    d2: getSQLDate(frontData.date_finish),
    id_hiking: frontData.hiking ? frontData.hiking.id : null,
    main: frontData.isMain ? 1 : 0,
  };
};

export const mapQuestionBaseToBack = (
  frontData: IQuestionBase,
  id_iv: number,
): IQuestionBaseUpdateOrAddDTO => {
  return {
    id_iv,
    id_qq: frontData.id,
    name: frontData.name,
    text: frontData.text,
    id_type: frontData.type,
    is_custom: frontData.isCustom ? 1 : 0,
    is_require: frontData.isRequire ? 1 : 0,
    is_private: frontData.isPrivate ? 1 : 0,
    is_multi: frontData.isMulti ? 1 : 0,
  };
};

export const mapQuestionInputParamsToBack = (
  frontData: IQuestionInputParams,
  id_qq: number,
): IQuestionInputParamsUpdateOrAddDTO => {
  return {
    id_qq,
    id: frontData.id,
    type: frontData.type,
    pattern: frontData.pattern,
    placeholder: frontData.placeholder,
    min: frontData.min,
    max: frontData.max,
    step: frontData.step,
  };
};

const mapQuestionType = (s: string): IQuestionType => {
  if (+s === 2) return IQuestionType.Select;
  if (+s === 3) return IQuestionType.Dir;

  return IQuestionType.Input;
};

export const mapQuestionTypeToFront = (backData: IIQuestionTypeDTO): IQuestionTypeObject => {
  return {
    id: +backData.type_id,
    name: backData.type_name,
    hint: backData.type_hint,
    canMulti: backData.type_is_multi_available === '1',
  };
};

const mapQuestionBase = (backData: IQuestionDTO): IQuestionBase => {
  return {
    id: +backData.id,
    name: backData.name,
    text: backData.text,

    isCustom: backData.is_custom === '1',
    isRequire: backData.is_require === '1',
    isMulti: backData.is_multi === '1',
    isPrivate: backData.is_private === '1',

    order_index: +backData.order_index,
    typeObject: {
      id: +backData.type_id,
      name: backData.type_name,
      hint: backData.type_hint,
      canMulti: backData.type_is_multi_available === '1',
    },
    type: mapQuestionType(backData.id_type),
  };
};

export const mapQuestionToFront = (backData: IQuestionDTO): IQuestion => {
  const base = mapQuestionBase(backData);

  if (base.type === IQuestionType.Select) {
    return {
      ...mapQuestionBase(backData),
      type: IQuestionType.Select,
      options:
        backData.variants?.map(([id, value, order_index]) => ({
          id: +id,
          value,
          order_index: +order_index,
        })) ?? [],
    } satisfies IQuestionSelect;
  }

  if (base.type === IQuestionType.Dir) {
    const [id, id_dir, name, desc, table, field, value, is_equall] = backData.dir_params ?? [];
    return {
      ...mapQuestionBase(backData),
      type: IQuestionType.Dir,
      dir: {
        id: +id,
        id_dir: +id_dir,
        name: name,
        desc: desc,
        table: table,
        field: field,
        value: value,
        isEqual: is_equall == '1',
      } satisfies IQuestionDirParams,
    } satisfies IQuestionDir;
  }

  const [id, type, pattern, placeholder, min, max, step] = backData.params ?? [];

  return {
    ...mapQuestionBase(backData),
    type: IQuestionType.Input,
    params: {
      id: +id,
      type,
      pattern,
      placeholder,
      min,
      max,
      step,
    } satisfies IQuestionInputParams,
  } satisfies IQuestionInput;
};

export const mapQuestionWithAnswerToFront = (
  backData: IQuestionWithMyAnswerDTO,
): IQuestionWithAnswer => {
  const base = mapQuestionToFront(backData);
  const user = {
    user: {
      id: +backData.user_id,
      name: backData.user_name,
      surname: backData.user_surname,
      photo: backData.user_photo,
    },
  } satisfies { user: IUser };
  // indexes: v_from_input, v_from_variants, v_from_dir, v_custom
  if (base.type === IQuestionType.Input) {
    return {
      ...base,
      ...user,
      answer_date: new Date(backData.answer_date),
      value: backData.answer?.[0][0] ?? '',
    } as IQuestionInputWithAnswer;
  } else if (base.type === IQuestionType.Select) {
    return {
      ...base,
      ...user,
      selectedIds: backData.answer?.filter((x) => +x[1] > 0).map((x) => +x[1]) ?? [],
      customValue: backData.answer?.find((x) => !!x[3])?.[3] ?? null,
      answer_date: new Date(backData.answer_date),
    };
  } else if (base.type === IQuestionType.Dir) {
    return {
      ...base,
      ...user,
      answer_date: new Date(backData.answer_date),
      selectedIds: backData.answer?.filter((x) => +x[2] > 0).map((x) => +x[2]) ?? [],
      customValue: backData.answer?.find((x) => !!x[3])?.[3] ?? null,
    };
  }

  throw new Error('Unknown type');
};

export const mapFrontInterviewToBack = (frontData: IInterview): IInterviewUpdateDTO => {
  return {
    id: frontData.id,
    name: frontData.name,
    desc: frontData.description,
    hello_text: frontData.hello_text,
    by_text: frontData.by_text,
    member_limit: frontData.members_limit,
    d1: getSQLDate(frontData.date_start),
    d2: getSQLDate(frontData.date_finish),
    id_hiking: frontData.hiking ? frontData.hiking.id : null,
    main: frontData.isMain ? 1 : 0,
  };
};
