import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapInterviewToFront,
  mapQuestionToFront,
  mapQuestionTypeToFront,
  mapQuestionWithAnswerToFront,
} from '../@mappers/interview.mapper';
import {
  IInterviewAddDTO,
  IInterviewDTO,
  IInterviewUpdateDTO,
  IIQuestionTypeDTO,
  IIvPrepareDTO,
  IQuestionBaseUpdateOrAddDTO,
  IQuestionDirParamsUpdateOrAddDTO,
  IQuestionDTO,
  IQuestionInputParamsUpdateOrAddDTO,
  IQuestionWithMyAnswerDTO,
} from '../@types/interview.types.dto';

export const getInterviewsList = async (data: { id_hiking: number } | {}) => {
  const res = await get('/ajax/iv/iv_list.php', data).then<IInterviewDTO[]>(handleApiError);
  return res.map(mapInterviewToFront);
};

export const getInterviewById = async (id: number) => {
  const res = await get('/ajax/iv/iv_one.php', { id }).then<IInterviewDTO>(handleApiError);
  return mapInterviewToFront(res);
};

export const addInterview = async (data: IInterviewAddDTO) => {
  const res = await post('/ajax/iv/iv_add.php', data).then<{ id: number }>(handleApiError);
  return res.id;
};

export const updateInterview = async (data: IInterviewUpdateDTO) => {
  const res = await post('/ajax/iv/iv_add.php', data).then<{ success: boolean }>(handleApiError);
  return res.success;
};

export const deleteInterviewById = async (id: number) => {
  const res = await post('/ajax/iv/iv_del.php', { id }).then<{ success: boolean }>(handleApiError);
  return res.success;
};

export const getQuestions = async (id_interview: number) => {
  const res = await get('/ajax/iv/iv_qq_list.php', { id: id_interview }).then<IQuestionDTO[]>(
    handleApiError,
  );
  return res.map(mapQuestionToFront);
};

export const addOrUpdateQuestionBase = async (data: IQuestionBaseUpdateOrAddDTO) => {
  const res = await post('/ajax/iv/iv_qq_save.php', data).then<{ id: number }>(handleApiError);
  return res.id;
};
export const deleteQuestion = async (id_qq: number) => {
  const res = await post('/ajax/iv/iv_qq_delete.php', { id_qq }).then<{ success?: number }>(
    handleApiError,
  );
  return res?.success;
};
export const reorderQuestion = async (data: { id: number; index: number }[]) => {
  const res = await post('/ajax/iv/iv_qq_order.php', { data }).then<{ success?: number }>(
    handleApiError,
  );
  return res?.success;
};

export const addOrUpdateQuestionInputParam = async (data: IQuestionInputParamsUpdateOrAddDTO) => {
  const res = await post('/ajax/iv/iv_qq_save_type_1.php', data).then<{ id?: number }>(
    handleApiError,
  );
  return res?.id ?? data.id;
};

export const addOrUpdateQuestionDirParam = async (data: IQuestionDirParamsUpdateOrAddDTO) => {
  const res = await post('/ajax/iv/iv_qq_save_type_3.php', data).then<{ id?: number }>(
    handleApiError,
  );
  return res?.id ?? data.id;
};

export const addOrUpdateQuestionSelectVariants = async (
  id_qq: number,
  data: { name: string; index: number }[],
) => {
  return post('/ajax/iv/iv_qq_save_type_2.php', { id_qq, data: JSON.stringify(data) }).then<
    { id: string; value: string; order_index: string }[]
  >(handleApiError);
};

export const interviewDirList = async () => {
  return get('/ajax/iv/iv_dir_list.php').then<{ id: string; name: string }[]>(handleApiError);
};

export const getQuestionTypes = async () => {
  const res = await get('/ajax/iv/iv_qq_types.php').then<IIQuestionTypeDTO[]>(handleApiError);
  return res.map(mapQuestionTypeToFront);
};

export const getIvStartData = (id: number) => {
  return get('/ajax/iv/iv_start_prepare.php', { id }).then<IIvPrepareDTO>(handleApiError);
};

export const finishIv = (data: Record<number, any>) => {
  return post('/ajax/iv/iv_finish.php', { data: JSON.stringify(data) }).then<{ success: boolean }>(
    handleApiError,
  );
};

export const getIvResultsForHiking = (id_hiking: number) => {
  return get('/ajax/hiking/iv_stat.php', { id: id_hiking }).then<IIvPrepareDTO>(handleApiError);
};

export const getQuestionsWithMyAnswer = async (id_interview: number) => {
  const res = await get('/ajax/iv/iv_results.php', { id: id_interview, my: 1 }).then<
    IQuestionWithMyAnswerDTO[]
  >(handleApiError);
  return res.map(mapQuestionWithAnswerToFront);
};
export const getQuestionsWithResults = async (id_interview: number) => {
  const res = await get('/ajax/iv/iv_results.php', { id: id_interview, my: 0 }).then<
    IQuestionWithMyAnswerDTO[]
  >(handleApiError);
  return res.map(mapQuestionWithAnswerToFront);
};
